import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Bienvenida from "./components/Bienvenida";

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Bienvenida />} />
        <Route path="/administrativas" element={<div>Sección Administrativas</div>} />
        <Route path="/ubicaciones" element={<div>Sección Ubicaciones</div>} />
      </Routes>
    </Router>
  );
}

export default App;
